import images from '../data/images.generated.json';

export type ImageKey = keyof typeof images;

interface Props {
  name: ImageKey;
  alt: string;
  className?: string;
  /** Above-the-fold images: eager + high fetch priority. */
  priority?: boolean;
  sizes?: string;
}

/** AVIF/WebP <picture> with intrinsic width/height (no layout shift). Generated by scripts/optimize-images.mjs. */
export default function Picture({ name, alt, className, priority = false, sizes }: Props) {
  const img = images[name];
  return (
    <picture>
      <source srcSet={img.avif} type="image/avif" sizes={sizes} />
      <source srcSet={img.webp} type="image/webp" sizes={sizes} />
      <img
        src={img.webp}
        alt={alt}
        width={img.width}
        height={img.height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
        className={className}
      />
    </picture>
  );
}
